PAYLOAD_SHA256 = 'ce0a0a95095220651bdccfe803a6727a0912138ccee1bd3cf1a9973b0a049d07'
BASELINE = 'ec10d8eb96993f03c9d327f87324f3d86f0feb54'

def digest(data): return hashlib.sha256(data).hexdigest()
def fail(message): raise SystemExit('STOP: ' + message + '\nNo update files were applied.')
args = sys.argv[1:]
if args in (['--help'], ['-h'], []):
    print('Run from your EXISTING IntelliJ repository root:')
    print('  bash <path-to-this-script> --check    # preflight only')
    print('  bash <path-to-this-script> --apply    # backup and update')
    print('  bash <path-to-this-script> --verify   # verify installed file hashes')
    print('Partial-parity Windows preview; read desktop/hyper_player/CONSOLIDATED_STATUS.md.')
    sys.exit(0)
if len(args) != 1 or args[0] not in ('--check', '--apply', '--verify'):
    fail('Use exactly --check, --apply or --verify. Use --help for instructions.')
mode = args[0]
try:
    top = subprocess.check_output(['git', 'rev-parse', '--show-toplevel'], stderr=subprocess.DEVNULL).decode().strip()
except (OSError, subprocess.CalledProcessError):
    fail('This directory is not an existing Git repository. Open its root terminal first.')
root = pathlib.Path(top).resolve()
if pathlib.Path.cwd().resolve() != root:
    fail('Run this script from the repository ROOT, not desktop/hyper_player or Downloads.')
if not (root / 'pubspec.yaml').is_file() or not (root / 'desktop/hyper_player/pubspec.yaml').is_file():
    fail('Expected existing Android repository plus desktop/hyper_player. This is an update, not a fresh installer.')
compressed = base64.b64decode(PAYLOAD)
if digest(compressed) != PAYLOAD_SHA256: fail('Embedded payload checksum failed; download the script again.')
entries = json.loads(gzip.decompress(compressed))
seen = set()
for entry in entries:
    rel = pathlib.PurePosixPath(entry['path'])
    if rel.is_absolute() or '..' in rel.parts or entry['path'] in seen:
        fail('Invalid or duplicate payload path.')
    if not (entry['path'].startswith('desktop/hyper_player/') or entry['path'] == '.github/workflows/windows-preview.yml'):
        fail('Payload contains a non-desktop/non-Windows-workflow path.')
    seen.add(entry['path'])
    data = base64.b64decode(entry['data'])
    if digest(data) != entry['after']: fail('Payload file checksum failed: ' + entry['path'])
    entry['_bytes'] = data

def inspect(rel):
    target = root / rel
    for path in [target, *target.parents]:
        if path == root: break
        if path.is_symlink(): fail('Symlink/reparse-style path refused: ' + str(path))
    if target.exists() and not target.is_file(): fail('Not a regular file: ' + rel)
    return target.read_bytes() if target.exists() else None

conflicts, changes, snapshots = [], [], {}
for entry in entries:
    rel = entry['path']
    current = inspect(rel)
    current_hash = None if current is None else digest(current)
    if mode == '--verify':
        if current_hash != entry['after']: conflicts.append(rel)
        continue
    if current_hash == entry['after']: continue
    if current_hash != entry['before']:
        conflicts.append(rel)
        continue
    changes.append(entry)
    snapshots[rel] = (current, stat.S_IMODE((root / rel).stat().st_mode) if current is not None else None)
if conflicts:
    print('Files requiring attention (nothing was overwritten):', file=sys.stderr)
    for rel in conflicts: print('  ' + rel, file=sys.stderr)
    if mode == '--verify': fail('Installed files do not match this update.')
    fail('Desktop/workflow content differs from the supported baseline or this update. Preserve your work; do NOT force/reset. Share the conflicting filenames for a merge.')
if mode == '--verify':
    print('VERIFIED: all %d delivered file hashes match.' % len(entries))
    sys.exit(0)
print('Supported desktop baseline: ' + BASELINE)
print('Payload: %d files; %d need updates; %d already match.' % (len(entries), len(changes), len(entries)-len(changes)))
print('Scope: desktop/hyper_player and Windows workflow ONLY. Android source/signing/version untouched.')
if mode == '--check':
    print('CHECK PASSED. No update files written. Run with --apply to install.')
    sys.exit(0)
if not changes:
    print('Already applied. No files changed; rerun is safe.')
    sys.exit(0)
git_backup = subprocess.check_output(['git', 'rev-parse', '--git-path', 'hyper-consolidated-backups']).decode().strip()
backup_parent = pathlib.Path(git_backup)
if not backup_parent.is_absolute(): backup_parent = root / backup_parent
backup = backup_parent / datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%dT%H%M%S.%fZ')
backup.mkdir(parents=True, exist_ok=False)
backup_manifest = []
for entry in changes:
    rel = entry['path']
    original, original_mode = snapshots[rel]
    backup_manifest.append({'path': rel, 'existed': original is not None, 'mode': original_mode, 'sha256': None if original is None else digest(original)})
    if original is not None:
        saved = backup / 'files' / rel
        saved.parent.mkdir(parents=True, exist_ok=True)
        saved.write_bytes(original)
(backup / 'manifest.json').write_text(json.dumps(backup_manifest, indent=2) + '\n')

def atomic_write(path, data, permissions):
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, temporary = tempfile.mkstemp(prefix='.hyper-update-', dir=str(path.parent))
    try:
        with os.fdopen(fd, 'wb') as out:
            out.write(data)
            out.flush()
            os.fsync(out.fileno())
        os.chmod(temporary, permissions & 0o777)
        os.replace(temporary, path)
    finally:
        if os.path.exists(temporary): os.unlink(temporary)

written = []
try:
    for entry in changes:
        rel = entry['path']
        original, original_mode = snapshots[rel]
        if inspect(rel) != original: raise RuntimeError('File changed while applying: ' + rel)
        atomic_write(root / rel, entry['_bytes'], original_mode if original_mode is not None else entry['mode'])
        written.append(rel)
    for entry in entries:
        if digest((root / entry['path']).read_bytes()) != entry['after']:
            raise RuntimeError('Post-apply hash mismatch: ' + entry['path'])
except BaseException:
    print('Apply failed; restoring files written by this run.', file=sys.stderr)
    for rel in reversed(written):
        original, original_mode = snapshots[rel]
        try:
            if original is None: (root / rel).unlink(missing_ok=True)
            else: atomic_write(root / rel, original, original_mode)
        except Exception as error:
            print('Manual restore needed for %s from %s: %s' % (rel, backup, error), file=sys.stderr)
    raise
print('APPLIED and hash-verified %d updated files.' % len(changes))
print('Backup (inside Git metadata, not staged): ' + str(backup))
print('No dependencies installed, no Android build, no Git commit/push and no remote workflow triggered.')
print('Read desktop/hyper_player/CONSOLIDATED_STATUS.md for implemented features and remaining gaps.')
print('Next: git diff --check, review changes, commit/push, then manually run Windows desktop preview Actions.')
HYPER_CONSOLIDATED_PYTHON
